pairs(2094,[('(situación de la empresa; queda como solicitud)','(situación de la empresa; dato no disponible al cierre)'),('lleva el VAN del AMI a USD 13,1 millones y el del programa a USD 15,46 millones — y converge','lleva el VAN del componente a USD 12,4 millones, con su O&M, y el del Programa, antes de los beneficios de confiabilidad, a USD 14,74 millones — y converge'),('El escenario E4 es la lectura recomendada del componente de medición inteligente, sin los canales de continuidad; E3 (27,0 GWh)','El escenario E4 es la lectura recomendada del componente de medición inteligente; E3 (27,0 GWh)')])
