pairs(2387,[('la banda de escenarios del AMI con la prima CNEL sustentada y el ahorro operativo mueven el resultado a USD +8.955.224 (base E3) y el ajuste de focalización al escenario base E4 lo sitúa en USD +15.459.050, con cota en +7,64 y tope en +34,12 millones; los umbrales de este párrafo se re-expresan sumando +6.503.826 sobre la base E4.','la banda de escenarios del AMI con la prima CNEL sustentada y el ahorro operativo mueven el resultado a USD +8.955.224 (base E3), el ajuste de focalización lo sitúa en USD +15.459.050 y el O&M de la medición inteligente lo deja en +14.739.396; los beneficios de confiabilidad y la regla de transferencias llevan el resultado publicado a +33.101.388 (apartado 7.7). Los umbrales de este párrafo se refieren a la reestimación corregida y se conservan como memoria; los vigentes están en el capítulo 8.')])
pairs(2388,[('Un valor actual neto de USD 15.459.050 en la base E4 (lectura prudente E3: 8.955.224; piso metodológico de la reestimación corregida: USD 731.265) con una tasa interna de retorno de 14,84 %, construido','Un valor actual neto de USD 33.101.388 en el resultado publicado (base del componente antes de los beneficios de confiabilidad: 14.739.396; piso metodológico de la reestimación corregida: USD 731.265) con una tasa interna de retorno de 18,34 %, construido')])
